// One request per agent and month: a later batch with newer figures sends the same idempotency key with another body,
// which Landledger answers 409. That means "already asked this month"; any other failure stops the run.
const failed = $json.error ? String($json.error.message ?? $json.error) : '';
if (failed && !/Landledger API error 409/.test(failed)) throw new Error(failed);
const plan = $('Over the threshold').item.json;
return {
  agentId: plan.agentId, month: plan.month,
  asked: !failed, alreadyAsked: Boolean(failed),
  requestId: $json.request?.id ?? null, status: $json.request?.status ?? null,
};

// Settings for the raise: where Landflow's API is (the same as Settings above) and the most a raise may set.
const LANDFLOW_URL = 'http://localhost:3000';
const MAX_CAP = 5000;      // never raise a monthly cap above this, whatever was approved
const MAX_ATTEMPTS = 3;    // a raise whose publish keeps failing is retried this often, then left to a person
return {
  requestId: $json.requestId ?? $json.id, landflowUrl: LANDFLOW_URL.replace(/\/+$/, ''), maxCap: MAX_CAP, maxAttempts: MAX_ATTEMPTS,
  month: new Date().toISOString().slice(0, 7),
};

