// For each approved request: trust it only if this flow's key raised it (createdBy), it is an approved ai_budget whose
// origin Landledger verified (a key bound to this workflow), and it names a real agent. The new cap is the cap in force
// plus the approved amount (never the evidence's figure), at most one automatic raise per agent per month, and a raise
// already made is finished rather than made twice (reconcile).
const settings = $('Raise settings').all();
const gets = $('Get the request').all();
const mes = $('Who is this flow').all();
const reads = $('Read the agent now').all();
const rows = $input.all().map((i) => i.json).filter((r) => r.request_id);
const money = (n) => Math.round(n * 100) / 100;
const same = (a, b) => JSON.stringify(a ?? null) === JSON.stringify(b ?? null);
return gets.map((g, i) => {
  const s = settings[i].json;
  const r = g.json.request ?? {};
  const me = mes[i]?.json ?? {};
  const agent = reads[i]?.json?.agent;
  const published = agent?.published?.config;
  const capOf = (settingsObject) => Number((settingsObject ?? {}).monthlyCostLimit ?? 0);
  const publishedCap = capOf(published?.settings ?? agent?.settings);
  const draftCap = capOf(agent?.settings);
  const amount = Number(r.amount?.amount ?? 0);
  const row = rows.find((x) => x.request_id === r.id);
  const base = {
    requestId: r.id, number: r.number ?? null, agentId: agent?.id ?? null, agentName: agent?.name ?? null, landflowUrl: s.landflowUrl,
    month: s.month, oldCap: publishedCap, publish: Boolean(published), attempts: Number(row?.attempts ?? 0),
  };
  const out = (action, why, extra = {}) => ({ json: { ...base, action, why, ...extra }, pairedItem: { item: i } });
  if (r.status === 'applied') return out('skip', 'Already applied');
  if (r.createdBy?.kind !== 'key' || !me.id || r.createdBy.id !== me.id) return out('hold', `Raised by ${r.createdBy?.name ?? 'someone else'}, not this flow's key`);
  if (r.kind !== 'ai_budget') return out('hold', `A ${r.kind} request, not an ai_budget`);
  if (r.status !== 'approved') return out('hold', `Landledger says it is ${r.status}, not approved`);
  if (r.origin?.type !== 'landflow_run' || r.origin.workflowId !== $workflow.id || r.origin.verified !== true) {
    return out('hold', 'Its origin is not verified as this workflow: bind this flow\'s Landledger key to the workflow (boundWorkflowIds)');
  }
  if (r.requester?.kind !== 'agent' || !agent || agent.id !== r.requester.agent?.id) return out('hold', 'The request does not name this agent');
  if (!(amount > 0)) return out('hold', 'The approved amount is not above zero');
  if (row) {
    // A raise this flow began for this request: finish it (reconcile) rather than add the amount again.
    const target = Number(row.new_cap);
    const extra = { newCap: target, oldCap: Number(row.old_cap), settings: { ...(agent.settings ?? {}), monthlyCostLimit: target }, revert: { ...(agent.settings ?? {}), monthlyCostLimit: Number(row.old_cap) } };
    if (publishedCap === target) return out('markApplied', `The cap is already $${target}: mark it applied`, extra);
    if (base.attempts >= s.maxAttempts) return out('hold', `Publishing the raise failed ${base.attempts} times: raise it by hand, then mark the request applied`, extra);
    if (published && draftCap === target) return out('publish', 'Saved but not published: publish again', { ...extra, attempts: base.attempts + 1 });
    return out('raise', 'Raise again after a failed publish', { ...extra, attempts: base.attempts + 1 });
  }
  const recent = (x) => x.status !== 'raising' || Date.now() - Date.parse(x.updated_at) < 15 * 60 * 1000;
  const other = rows.find((x) => x.agent_id === agent.id && x.month === s.month && x.request_id !== r.id && ['raising', 'applied'].includes(x.status) && recent(x));
  if (other) return out('hold', `${agent.name}'s cap was already raised this month (${other.request_id}): one automatic raise per agent per month`);
  if (!(publishedCap > 0)) return out('hold', `${agent.name} has no monthly cap to raise`);
  const newCap = money(publishedCap + amount);
  if (newCap > s.maxCap) return out('hold', `The new cap ($${newCap}) is above the flow's limit ($${s.maxCap})`);
  const draftChanged = published ? Object.keys(published).some((k) => !same(agent[k], published[k])) : false;
  if (draftChanged) return out('hold', `${agent.name} has unpublished changes: raise the cap by hand, then mark the request applied`);
  return out('raise', `Raise from $${publishedCap} by $${amount} to $${newCap}`, {
    newCap, attempts: 1,
    settings: { ...(agent.settings ?? {}), monthlyCostLimit: newCap },
    revert: { ...(agent.settings ?? {}), monthlyCostLimit: publishedCap },
  });
});
